fn coordinator_from_summary(summary: &FormatSummary) -> RewriteCoordinator {
    let mut coordinator = RewriteCoordinator::new();
    coordinator.set_format_analysis(
        summary.autos.clone(),
        summary.indices.clone(),
        summary.keywords.clone(),
        summary.has_nested_parts,
    );
    coordinator
}

pub(crate) fn extra_positional_indexes(summary: &FormatSummary, args: &[Expr]) -> Vec<usize> {
    coordinator_from_summary(summary).extra_positional_indexes(args)
}

pub(crate) fn extra_named_keyword_indexes(
    summary: &FormatSummary,
    keywords: &[ast::Keyword],
